{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "Massive iron gates hang askew, their hinges rusted. The glass diver stands before them, his helmet reflecting the crumbling towers beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfurls a map under a broken archway.",
      "visual_description": "Mara traces ink lines on a worn parchment, her compass glinting. The archway is carved with faded royal crests.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "A spiral tower leans precariously, its windows glowing with blue light. The oracle lamp's single eye flickers in concern.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Tin fox scouts the main courtyard, avoiding a patrol.",
      "visual_description": "Tin fox scurries behind a fallen statue, its key-wind tail ticking. Armored figures march past in the distance.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector snores in a collapsed guardhouse.",
      "visual_description": "Papers flutter around a dozing figure slumped over a ledger. Stamped receipts cling to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara finds a secret passage beneath an old royal banner.",
      "visual_description": "A tattered banner with a faded coat of arms hangs from a wall. Mara pulls it aside to reveal a dark stairway.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through a mirror into a locked chamber.",
      "visual_description": "The glass diver presses his helmet against a silver mirror, his reflection rippling as he passes through into a dusty room.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin fox discovers a trap behind a magic door.",
      "visual_description": "A door inscribed with glowing runes stands slightly ajar. Tin fox's blue eyes detect pressure plates beneath the floor.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp illuminates a cursed corridor.",
      "visual_description": "The lamp's flame casts shifting shadows on walls lined with faded frescoes. A faint whisper echoes from the darkness.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Mara charts a path around an armored patrol's route.",
      "visual_description": "Mara kneels behind a crumbled wall, sketching a quick detour on her map. Armored figures clank past nearby.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes briefly, then dozes off again.",
      "visual_description": "He stirs, blinks at the group, mumbles 'taxes are due,' and returns to his ledger pillow.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver rescues a trapped ally from a mirror maze.",
      "visual_description": "Inside a hall of cracked mirrors, the glass diver guides a disoriented figure through reflections to freedom.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Tin fox disarms a magical trap near the inner gate.",
      "visual_description": "Tin fox inserts its tail into a clockwork mechanism, stopping a swinging blade just inches from the path.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp reveals a false wall hiding the escape route.",
      "visual_description": "The lamp's glow intensifies on a section of brickwork, showing faint mortar lines of a hidden door.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Mara leads the group through a crumbling tower stairwell.",
      "visual_description": "Broken steps spiral upward; Mara follows her compass, urging others to hurry as dust falls from above.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector is carried across a narrow bridge.",
      "visual_description": "The group crosses a stone bridge spanning a chasm. The tax collector is slung over a shoulder, still asleep.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "Tin fox holds the bridge as the others escape.",
      "visual_description": "Tin fox stands at the bridge's end, winding its tail to activate a collapsing mechanism, blue eyes fixed on the pursuing armored figures.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The group reaches safety beyond the ruined city.",
      "visual_description": "At a hilltop overlooking the city, the glass diver removes his helmet. Mara folds her map. The oracle lamp dims. Tin fox rejoins them, its key-wind tail slowing.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

